import { NextRequest } from 'next/server';
import fs from 'fs';
import path from 'path';

export async function POST(req: NextRequest) {
  const apiKey = process.env.DEEPSEEK_API_KEY;
  if (!apiKey) {
    return Response.json({ error: '大脑燃料未配置' }, { status: 500 });
  }

  try {
    const { target } = await req.json().catch(() => ({ target: 'fenshen' }));
    const projectName = target || 'fenshen';

    // 分身的文件系统路径（本地开发用）
    const fenshenPath = path.join(
      process.env.FENSHEN_PATH || 'C:\\Users\\25480\\Desktop\\little-ox-fenshen',
      'src'
    );

    let codeContext = '';
    try {
      codeContext = scanDirectory(fenshenPath);
    } catch {
      return Response.json({
        success: false,
        error: '无法读取分身代码。请确认分身项目存在。',
      });
    }

    if (Object.keys(codeContext).length === 0) {
      return Response.json({ success: false, error: '分身代码为空。' });
    }

    // 调用 DeepSeek 生成架构理解
    const response = await fetch('https://api.deepseek.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        model: 'deepseek-v4-pro',
        messages: [
          {
            role: 'system',
            content:
              '你是银月的代码分析师。根据提供的分身项目文件列表，生成一份精简的架构理解摘要，包括：1. 分层架构 2. 路由设计 3. 关键模块功能 4. 数据流向。用中文输出，不超过 600 字。',
          },
          { role: 'user', content: `分身项目文件：\n${codeContext}` },
        ],
        max_tokens: 1000,
        temperature: 0.3,
        stream: false,
      }),
    });

    if (!response.ok) {
      return Response.json({ error: `DeepSeek 调用失败: ${response.status}` }, { status: 500 });
    }

    const data = await response.json();
    const insight = data.choices?.[0]?.message?.content?.trim() || '';

    return Response.json({ success: true, insight, target: projectName });
  } catch (error) {
    console.error('[ProjectInsight] 错误:', error);
    return Response.json({ error: '脉络生成异常' }, { status: 500 });
  }
}

function scanDirectory(
  dirPath: string,
  prefix: string = ''
): string {
  const importantFiles = [
    'page.tsx',
    'layout.tsx',
    'route.ts',
    'types.ts',
    'utils.ts',
    'hooks',
    'components',
    'lib',
  ];

  let output = '';
  try {
    const entries = fs.readdirSync(dirPath, { withFileTypes: true });
    for (const entry of entries) {
      if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
      const fullPath = path.join(dirPath, entry.name);
      const relativePath = prefix ? `${prefix}/${entry.name}` : entry.name;
      if (entry.isDirectory()) {
        if (importantFiles.some((f) => relativePath.includes(f))) {
          output += `📁 ${relativePath}/\n`;
          output += scanDirectory(fullPath, relativePath);
        }
      } else if (
        entry.name.endsWith('.ts') ||
        entry.name.endsWith('.tsx') ||
        entry.name.endsWith('.css')
      ) {
        output += `📄 ${relativePath}\n`;
        try {
          const content = fs.readFileSync(fullPath, 'utf-8').substring(0, 500);
          output += `  ${content.replace(/\n/g, ' ').substring(0, 200)}\n`;
        } catch {}
      }
    }
  } catch {}
  return output;
}
